import React, { useState } from "react";
import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Collapse,
} from "reactstrap";
import { getDatabase, ref, set, get } from "firebase/database";
import { useAuthState } from "react-firebase-hooks/auth"; // Corrected import

const CarbonFootprintInput = () => {
  const [user] = useAuthState(auth); // Use the Firebase authentication instance
  const [collapse, setCollapse] = useState({
    transportation: false,
    energy: false,
    food: false,
    waste: false,
    sustainable: false,
    offset: false,
    additionalNotes: false,
  });

  const [userData, setUserData] = useState({
    carUsageKm: "",
    vehicleType: "",
    fuelType: "",
    publicTransportTrips: "",
    publicTransportMode: "",
    flightsPerYear: "",
    electricityUsage: "",
    heatingMethod: "",
    homeSize: "",
    energyEfficientAppliances: false,
    dietType: "",
    meatFrequency: "",
    recyclingHabit: false,
    wasteGeneration: "",
    renewableEnergyUse: false,
    ecoFriendlyProducts: false,
    sustainableShopping: false,
    carbonOffsetProgram: "",
    carbonOffsetDetails: "",
    additionalNotes: "",
  });

  const handleChange = (e) => {
    const { id, value, type, checked } = e.target;
    setUserData({
      ...userData,
      [id]: type === "checkbox" ? checked : value,
    });
  };

  const toggleCollapse = (section) => {
    setCollapse((prevState) => ({
      ...prevState,
      [section]: !prevState[section],
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!user) {
      console.log("User is not authenticated.");
      return;
    }

    const db = getDatabase();
    const userId = user.uid; // Get user ID from Firebase Authentication

    // Check if userfootprint exists, if not create it
    const userFootprintRef = ref(db, `users/${userId}/userfootprint`);
    const snapshot = await get(userFootprintRef);
    if (!snapshot.exists()) {
      console.log("Creating userfootprint node...");
      // Initialize the userfootprint node with default empty data if not present
      await set(userFootprintRef, userData);
    } else {
      console.log("Updating existing userfootprint...");
      // Update user data if it already exists
      await set(userFootprintRef, userData);
    }

    console.log("User footprint data saved to Firebase:", userData);
  };

  return (
    <>
      <Container className="mt--7" fluid>
        <Row>
          <Col xl="12">
            <Card className="shadow">
              <CardHeader>
                <h3 className="mb-0">Track Your Carbon Footprint</h3>
                <p className="text-muted">
                  Fill out the form to estimate and track your carbon footprint.
                </p>
              </CardHeader>
              <CardBody>
                <Form onSubmit={handleSubmit}>
                  {/* Transportation Section */}
                  <h6 className="heading-small text-muted mb-4">
                    Transportation
                    <Button
                      color="link"
                      onClick={() => toggleCollapse("transportation")}
                      size="sm"
                      className="float-right"
                    >
                      {collapse.transportation ? "Hide" : "Show"} Details
                    </Button>
                  </h6>
                  <Collapse isOpen={collapse.transportation}>
                    <Row>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="carUsageKm">
                            Number of kilometers driven daily
                          </label>
                          <Input
                            id="carUsageKm"
                            type="number"
                            value={userData.carUsageKm}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="vehicleType">Type of vehicle</label>
                          <Input
                            id="vehicleType"
                            type="text"
                            value={userData.vehicleType}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="fuelType">Fuel type</label>
                          <Input
                            id="fuelType"
                            type="text"
                            value={userData.fuelType}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                    </Row>
                    <Row>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="publicTransportTrips">
                            Number of trips taken weekly
                          </label>
                          <Input
                            id="publicTransportTrips"
                            type="number"
                            value={userData.publicTransportTrips}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="publicTransportMode">
                            Mode of transport
                          </label>
                          <Input
                            id="publicTransportMode"
                            type="text"
                            value={userData.publicTransportMode}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="flightsPerYear">
                            Number of flights per year
                          </label>
                          <Input
                            id="flightsPerYear"
                            type="number"
                            value={userData.flightsPerYear}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                    </Row>
                  </Collapse>

                  {/* Energy Consumption Section */}
                  {/* Similar sections for Energy, Food, Waste, etc. */}

                  {/* Submit Button */}
                  <div className="text-center mt-4">
                    <Button color="primary" type="submit">
                      Submit
                    </Button>
                  </div>
                </Form>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default CarbonFootprintInput;
